using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<pair<long long,long long>> d(n);
        for(auto &x : d) scanf("%lld %lld",&x.first,&x.second);
        sort(d.begin(), d.end());
        vector<long long> suf(n+1, -1);
        for(int i=n-1;i>=0;i--) suf[i]=max(suf[i+1], d[i].second);
        multiset<long long> R;   // b-values of departments before p (free)
        long long best = LLONG_MAX;
        for(int p=0;p<n;p++){
            long long X = d[p].first;          // p goes to friend 1, so m1 = X
            bool hasF = p+1 < n;
            long long B = hasF ? suf[p+1] : -1; // forced to friend 2 (indices > p)
            if(hasF) best = min(best, llabs(X - B));
            if(!R.empty()){
                auto it = R.lower_bound(max(B, X));
                if(it != R.end()) best = min(best, *it - X);
                auto up = R.upper_bound(X);
                if(up != R.begin()){
                    auto pr = prev(up);
                    if(*pr >= B) best = min(best, X - *pr);
                }
            }
            R.insert(d[p].second);
        }
        printf("%lld\n", best);
    }
}

#include <bits/stdc++.h>
