int main(){
    int T; scanf("%d",&T);
    while(T--){
        long long n,l,r; scanf("%lld %lld %lld",&n,&l,&r);
        long long N = n*(n-1)+1;
        // cycle = pairs (i,j), i<j in lex order, each emitted as "i j", then a final 1
        long long idx = (l-1)/2, i = 1;
        while(i < n && idx >= n-i){ idx -= n-i; i++; }
        long long j = i+1+idx;
        vector<long long> out;
        for(long long p=l;p<=r;p++){
            if(p==N){ out.push_back(1); break; }
            if((p-1)%2==0) out.push_back(i);
            else { out.push_back(j); j++; if(j>n){ i++; j=i+1; } }
        }
        for(size_t k=0;k<out.size();k++) printf("%lld%c",out[k], k+1==out.size()?'\n':' ');
    }
}

