int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n,m,k; scanf("%d %d %d",&n,&m,&k);
        vector<long long> a(n), d(m), f(k);
        for(auto &x:a) scanf("%lld",&x);
        for(auto &x:d) scanf("%lld",&x);
        for(auto &x:f) scanf("%lld",&x);
        sort(f.begin(), f.end());
        long long G=0; int cnt=0, p=-1;
        for(int i=0;i+1<n;i++){
            long long g=a[i+1]-a[i];
            if(g>G){ G=g; cnt=1; p=i; } else if(g==G) cnt++;
        }
        if(cnt>=2){ printf("%lld\n",G); continue; }   // any insertion keeps a gap of size G
        long long M=0;
        for(int i=0;i+1<n;i++) if(i!=p) M=max(M,a[i+1]-a[i]);
        long long L=a[p], R=a[p+1], best=G;
        for(auto dv:d){
            long long want=(L+R)/2 - dv;               // f closest to midpoint minus d
            int idx=lower_bound(f.begin(), f.end(), want)-f.begin();
            for(int c=idx-1;c<=idx;c++){
                if(c<0||c>=k) continue;
                long long x=dv+f[c];
                if(x>L && x<R) best=min(best, max(M, max(x-L, R-x)));
            }
        }
        printf("%lld\n",best);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    const long long S = 1000000000000LL, D = S + 1, INF = LLONG_MAX / 4;
    int t; scanf("%d", &t);
    static char buf[300005];
    while(t--){
        scanf("%s", buf);
        // state c = kept ones so far, capped at 2; cost = S*(swaps) + D*(deletions)
        long long cur[3] = {0, INF, INF};
        for(int i = 0; buf[i]; i++){
            long long nd[3] = {INF, INF, INF};
            for(int c = 0; c < 3; c++){
                long long v = cur[c];
                if(v >= INF) continue;
                nd[c] = min(nd[c], v + D);                      // delete
                if(buf[i] == '0'){
                    if(c < 2) nd[c] = min(nd[c], v + c * S);    // keep: swaps past c kept ones
                } else {
                    int nc = min(c + 1, 2);                     // keep a one
                    nd[nc] = min(nd[nc], v);
                }
            }
            memcpy(cur, nd, sizeof cur);
        }
        printf("%lld\n", min(cur[0], min(cur[1], cur[2])));
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d", &t);
    static char s[200005];
    while(t--){
        scanf("%s", s);
        int n = strlen(s), bad = 0, ans = INT_MAX, b = 0;
        vector<char> in(n, 0);
        long long c[26] = {0}, h[26] = {0};   // c: letters inside; h: outside partners of half pairs
        for(int i = 0; i < n/2; i++) bad += s[i] != s[n-1-i];
        auto feas = [&]{
            if(bad) return false;
            for(int x = 0; x < 26; x++) if(c[x] < h[x]) return false;
            return true;
        };
        auto add = [&](int p){
            int q = n-1-p, x = s[p]-'a', y = s[q]-'a';
            c[x]++; in[p] = 1;
            if(!in[q]){ bad -= x != y; h[y]++; } else h[x]--;
        };
        auto rem = [&](int p){
            int q = n-1-p, x = s[p]-'a', y = s[q]-'a';
            c[x]--; in[p] = 0;
            if(!in[q]){ bad += x != y; h[y]--; } else h[x]++;
        };
        for(int a = 0; a < n; a++){
            if(b < a) b = a;
            while(b < n && !feas()) add(b++);
            if(!feas()) break;
            ans = min(ans, b - a);
            if(a < b) rem(a);
        }
        printf("%d\n", ans);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    static char buf[200005];
    scanf("%s", buf);
    int n = strlen(buf);
    int c[26] = {0};
    for(int i = 0; i < n; i++) c[buf[i]-'a']++;
    vector<int> odd;
    for(int x = 0; x < 26; x++) if(c[x] & 1) odd.push_back(x);
    auto build = [&](int cc[26], int mid){
        string left;
        for(int x = 0; x < 26; x++) left += string(cc[x]/2, 'a'+x);
        string res = left;
        if(mid >= 0) res.push_back('a'+mid);
        res += string(left.rbegin(), left.rend());
        return res;
    };
    string best;
    if(n % 2 == 0){
        int k = odd.size(), cc[26];
        memcpy(cc, c, sizeof c);
        for(int i = 0; i < k/2; i++){ cc[odd[i]]++; cc[odd[i+k/2]]--; }
        best = build(cc, -1);
    } else {
        for(int m : odd){
            vector<int> R;
            for(int x : odd) if(x != m) R.push_back(x);
            int h = R.size()/2, cc[26];
            memcpy(cc, c, sizeof c);
            for(int i = 0; i < h; i++){ cc[R[i]]++; cc[R[i+h]]--; }
            string cand = build(cc, m);
            if(best.empty() || cand < best) best = cand;
        }
    }
    printf("%s\n", best.c_str());
}

