#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d", &t);
    while(t--){
        int n; scanf("%d", &n);
        vector<vector<int>> rows(n);
        vector<int> T, start(n), len(n);
        for(int i = 0; i < n; i++){
            int k; scanf("%d", &k); rows[i].resize(k); len[i] = k; start[i] = T.size();
            for(auto &x : rows[i]){ scanf("%d", &x); T.push_back(x); }
            T.push_back(0);                       // row separator (smallest value)
        }
        int N = T.size(), maxL = *max_element(len.begin(), len.end());
        // suffix ranks by prefix doubling
        vector<int> sa(N), rk(T.begin(), T.end()), tmp(N);
        iota(sa.begin(), sa.end(), 0);
        for(int h = 1; ; h <<= 1){
            auto key = [&](int i){ return make_pair(rk[i], i + h < N ? rk[i+h] : -1); };
            sort(sa.begin(), sa.end(), [&](int a, int b){ return key(a) < key(b); });
            tmp[sa[0]] = 0;
            for(int i = 1; i < N; i++) tmp[sa[i]] = tmp[sa[i-1]] + (key(sa[i-1]) < key(sa[i]));
            rk = tmp;
            if(rk[sa[N-1]] == N-1) break;
        }
        // greedy: pick the row whose suffix after the covered prefix is lexicographically smallest
        vector<int> ans; int c = 0;
        while(c < maxL){
            int best = -1, br = INT_MAX;
            for(int r = 0; r < n; r++) if(len[r] > c && rk[start[r] + c] < br){ br = rk[start[r] + c]; best = r; }
            for(int j = c; j < len[best]; j++) ans.push_back(rows[best][j]);
            c = len[best];
        }
        for(size_t i = 0; i < ans.size(); i++) printf("%d%c", ans[i], i + 1 == ans.size() ? '\n' : ' ');
    }
}

