int main(){
    int t; scanf("%d", &t);
    while(t--){
        int n, k; scanf("%d %d", &n, &k);
        vector<int> b(n+1), st(n+1, 0);
        for(int i = 1; i <= n; i++) scanf("%d", &b[i]);
        bool ok = true;
        if(k == 1){                              // single-position op only sets a[i] = i
            for(int i = 1; i <= n; i++) if(b[i] != i) ok = false;
        }
        for(int i = 1; i <= n && ok && k > 1; i++){
            if(st[i]) continue;
            vector<int> path;
            int v = i;
            while(!st[v]){ st[v] = 1; path.push_back(v); v = b[v]; }
            if(st[v] == 1){                       // closed a new cycle at v
                int len = 0, u = v;
                do { len++; u = b[u]; } while(u != v);
                if(len != k) ok = false;
            }
            for(int x : path) st[x] = 2;
        }
        puts(ok ? "YES" : "NO");
    }
}

