        for(auto &x : a) scanf("%lld", &x);
        long long ans = k - 1;                     // k-th missing: start at k-1, bump past present values
        if(n == 1){
            if(a[0] <= ans) ans++;                 // n = 1: no operation possible, the set is {a[0]}
        } else {
            long long g = 0;
