    }
}

#include <bits/stdc++.h>
using namespace std;
struct DSU {
    vector<int> p; int comps;
    DSU(int n) : p(n), comps(n) { iota(p.begin(), p.end(), 0); }
    int f(int x){ return p[x] == x ? x : p[x] = f(p[x]); }
    void unite(int a, int b){ a = f(a); b = f(b); if(a != b){ p[a] = b; comps--; } }
};
int main(){
    int T; scanf("%d", &T);
    const long long INF = LLONG_MAX / 4;
    while(T--){
        int n, m; long long k; scanf("%d %d %lld", &n, &m, &k);
        vector<array<long long,3>> e(m);
        for(auto &ed : e){ long long x, y, s; scanf("%lld %lld %lld", &x, &y, &s); ed = {x-1, y-1, s}; }
        DSU d1(n), d3(n), d2(n);
        bool hasEq = false; long long minHigh = INF, maxLow = -1, sum = 0;
        for(auto &ed : e){
            if(ed[2] <= k){ d1.unite(ed[0], ed[1]); d2.unite(ed[0], ed[1]); }
            if(ed[2] < k){ d3.unite(ed[0], ed[1]); maxLow = max(maxLow, ed[2]); }
            if(ed[2] == k) hasEq = true;
            if(ed[2] > k) minHigh = min(minHigh, ed[2] - k);
        }
        long long caseA;
        if(d1.comps == 1) caseA = hasEq ? 0 : minHigh;   // Z = {s <= k} spans: one high edge suffices
        else {                                           // every tree needs a high edge: Kruskal on s - k
            vector<array<long long,3>> hi;
            for(auto &ed : e) if(ed[2] > k) hi.push_back(ed);
            sort(hi.begin(), hi.end(), [](auto &a, auto &b){ return a[2] < b[2]; });
            for(auto &ed : hi){ int a = d2.f(ed[0]), b = d2.f(ed[1]); if(a != b){ d2.unite(a, b); sum += ed[2] - k; } }
            caseA = sum;
        }
        long long caseB = (d3.comps == 1) ? k - maxLow : INF;   // all kept edges below k
        printf("%lld\n", min(caseA, caseB));
    }
}

