int main(){
    int T; scanf("%d", &T);
    while(T--){
        int n; static char sg[200005];
        scanf("%d %s", &n, sg);               // sg[i] relates positions i and i+1 (0-based)
        // min LIS: blocks split at '>' (each block is a '<'-run); blocks get decreasing value ranges
        vector<int> mn(n), mx(n);
        {
            int cur = n, i = 0;
            while(i < n){
                int j = i;
                while(j + 1 < n && sg[j] == '<') j++;   // block i..j
                int len = j - i + 1;
                for(int p = 0; p < len; p++) mn[i + p] = cur - len + 1 + p;   // ascending inside block
                cur -= len; i = j + 1;
            }
        }
        {
            int cur = 1, i = 0;
            while(i < n){
                int j = i;
                while(j + 1 < n && sg[j] == '>') j++;   // block i..j is a '>'-run
                int len = j - i + 1;
                for(int p = 0; p < len; p++) mx[i + p] = cur + len - 1 - p;   // descending inside block
                cur += len; i = j + 1;
            }
        }
        for(int i = 0; i < n; i++) printf("%d%c", mn[i], i + 1 == n ? '\n' : ' ');
        for(int i = 0; i < n; i++) printf("%d%c", mx[i], i + 1 == n ? '\n' : ' ');
    }
}

