#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d", &t);
    while(t--){
        int n; scanf("%d", &n);
        vector<long long> a(n);
        for(auto &x : a) scanf("%lld", &x);
        vector<int> kn;
        for(int i = 0; i < n; i++) if(a[i] != -1) kn.push_back(i);
        bool ok = true;
        if(kn.empty()){ for(int i = 0; i < n; i++) a[i] = i % 2 + 1; }
        else {
            int f = kn[0], l = kn.back();
            for(int i = f - 1; i >= 0; i--) a[i] = ((f - i) % 2) ? 2 * a[f] : a[f];   // alternate v, 2v
            for(int i = l + 1; i < n; i++) a[i] = ((i - l) % 2) ? 2 * a[l] : a[l];
            for(size_t q = 0; q + 1 < kn.size() && ok; q++){
                int L = kn[q], R = kn[q+1], g = R - L - 1;
                long long x = a[L], y = a[R], X = x, Y = y;
                vector<long long> px = {x}, py = {y};          // heap tree: parent of v is v/2
                while(X != Y){ if(X > Y){ X /= 2; px.push_back(X); } else { Y /= 2; py.push_back(Y); } }
                vector<long long> path = px;                   // x ... lca
                for(int i = (int)py.size() - 2; i >= 0; i--) path.push_back(py[i]);   // lca ... y
                int d = (int)path.size() - 1, e = g + 1 - d;
                if(e < 0 || e % 2){ ok = false; break; }
                vector<long long> walk = {x};
                long long w = (x >= 2) ? x / 2 : 2;
                for(int i = 0; i < e / 2; i++){ walk.push_back(w); walk.push_back(x); }
                for(int i = 1; i <= d; i++) walk.push_back(path[i]);
                for(int j = 0; j < g; j++) a[L + 1 + j] = walk[1 + j];
            }
        }
        if(!ok){ puts("-1"); continue; }
        for(int i = 0; i < n; i++) printf("%lld%c", a[i], i + 1 == n ? '\n' : ' ');
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d", &t);
    while(t--){
        int n, k; scanf("%d %d", &n, &k);
        vector<pair<int,int>> ch(k);
        vector<int> used(2*n + 1, 0);
        for(auto &c : ch){ scanf("%d %d", &c.first, &c.second); if(c.first > c.second) swap(c.first, c.second); used[c.first] = used[c.second] = 1; }
        // free points in sorted order; F = number of free points, m = new chords
        vector<int> pre(2*n + 2, 0);                  // pre[x] = free points <= x
        for(int x = 1; x <= 2*n; x++) pre[x] = pre[x-1] + (!used[x]);
        int F = pre[2*n], m = n - k;
        long long ans = (long long)m * (m - 1) / 2;   // new chords pairwise crossing
        for(size_t i = 0; i < ch.size(); i++){
            int in = pre[ch[i].second - 1] - pre[ch[i].first];   // free points strictly inside
            ans += min(in, F - in);                              // crossings with this chord
            for(size_t j = i + 1; j < ch.size(); j++){
                int a = ch[i].first, b = ch[i].second, c = ch[j].first, d = ch[j].second;
                if((a < c && c < b && b < d) || (c < a && a < d && d < b)) ans++;
            }
        }
        printf("%lld\n", ans);
    }
}

