            if(pos < l || pos > r){ puts("-1"); continue; }
            int lo = l, hi = r, A = 0, B = 0, Greq = 0, Lreq = 0;
            while(lo <= hi){
                int mid = (lo + hi) / 2;
                if(mid == pos) break;
                if(pos < mid){ Greq++; if(p[mid] < k) A++; hi = mid - 1; }     // needs value > k
                else { Lreq++; if(p[mid] > k) B++; lo = mid + 1; }             // needs value < k
            }
            if(Greq > n - k || Lreq > k - 1){ puts("-1"); continue; }
            printf("%d\n", 2 * max(A, B));
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
// returns the start indices p such that reading the cyclic array forward from p is non-decreasing
vector<int> starts(const vector<int> &a){
    int n = a.size(), cd = 0, at = -1;
    for(int i = 0; i < n; i++) if(a[i] > a[(i+1) % n]){ cd++; at = i; }
    if(cd == 1) return {(at + 1) % n};
    return {};
}
int main(){
    int t; scanf("%d", &t);
    while(t--){
        int n; scanf("%d", &n);
        vector<int> a(n);
        for(auto &x : a) scanf("%d", &x);
        if(is_sorted(a.begin(), a.end())){ puts("0"); continue; }
        vector<int> rev(a.rbegin(), a.rend());
        vector<int> cand = starts(a);                    // orientation +1 targets
        for(int j : starts(rev)) cand.push_back(n - 1 - j);   // orientation -1 targets (backward reading)
        long long ans = LLONG_MAX;
        for(int p : cand){                              // start pointer is index 0 with first move = right shift
            long long r = p;
            ans = min(ans, min(r + 2, (long long)n - r));
        }
        printf("%lld\n", cand.empty() ? -1LL : ans);
    }
}

