        long long cnt[3];
        scanf("%lld %lld %lld", &cnt[0], &cnt[1], &cnt[2]);
        string s;
        long long last[3] = {-10, -10, -10};
        while(true){
            int best = -1;
            for(int c = 0; c < 3; c++){
                if(cnt[c] == 0) continue;
                if(!s.empty() && s.back() == L[c]) continue;                 // no equal neighbour
                if(s.size() >= 3 && s[s.size()-3] == L[c]) continue;         // no equal at distance 3
                if(best < 0 || cnt[c] > cnt[best] || (cnt[c] == cnt[best] && last[c] > last[best])) best = c;
            }
            if(best < 0) break;
            s.push_back(L[best]); cnt[best]--; last[best] = s.size() - 1;
        }
        printf("%s\n", s.c_str());
    }
}

#include <bits/stdc++.h>
using namespace std;
const int M = 2750135;
int main(){
    static int spf[M];
    vector<int> primes;
    for(int i = 2; i < M; i++){
        if(!spf[i]){ spf[i] = i; primes.push_back(i); }
        for(int p : primes){
            if(p > spf[i] || (long long)p * i >= M) break;
            spf[p * i] = p;
        }
    }
    int n; scanf("%d", &n);
    vector<int> cnt(M, 0);
    for(int i = 0; i < 2 * n; i++){ int x; scanf("%d", &x); cnt[x]++; }
    vector<int> a;
    // pass 1: composites in descending order are originals; their largest proper divisor x/spf[x] is removed
    for(int x = M - 1; x >= 4; x--){
        if(spf[x] == x || cnt[x] == 0) continue;
        int r = cnt[x];
        for(int j = 0; j < r; j++) a.push_back(x);
        cnt[x / spf[x]] -= r; cnt[x] = 0;
    }
    // pass 2: primes in ascending order; a prime x with remaining count is original, and it generates the x-th prime
    for(int x = 2; x <= 200000; x++){
        if(spf[x] != x || cnt[x] == 0) continue;
        int r = cnt[x];
        for(int j = 0; j < r; j++) a.push_back(x);
        cnt[primes[x - 1]] -= r; cnt[x] = 0;
    }
    for(size_t i = 0; i < a.size(); i++) printf("%d%c", a[i], i + 1 == a.size() ? '\n' : ' ');
}
